import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 6
    stream = io.StringIO(raw_csv, newline="")
    records = list(csv.reader(stream, delimiter=",", quotechar='"', strict=False))

    def is_numeric(value):
        return bool(re.fullmatch(r"\s*[+-]?\d+(?:[.)])?\s*", value))

    def looks_like_header(row):
        if not row:
            return False
        nonempty = [cell.strip() for cell in row if cell.strip()]
        if len(nonempty) < 3:
            return False
        text_cells = sum(bool(re.search(r"[A-Za-z]", cell)) for cell in nonempty)
        first = row[0].strip() if row else ""
        has_url = any(re.search(r"(?:https?://|www\.)", cell, re.I) for cell in row)
        return text_cells >= 3 and not is_numeric(first) and not has_url

    def looks_like_data(row):
        if not row:
            return False
        first = row[0].strip()
        has_url = any(re.search(r"(?:https?://|www\.)", cell, re.I) for cell in row)
        return is_numeric(first) or has_url

    header_index = None
    plausible = []
    for index, row in enumerate(records):
        if len(row) != expected_width or not looks_like_header(row):
            continue
        plausible.append(index)
        following = next(
            (candidate for candidate in records[index + 1:] if candidate),
            None,
        )
        if following is not None and looks_like_data(following):
            header_index = index
            break

    if header_index is None and plausible:
        header_index = plausible[0]

    if header_index is None:
        header_index = next(
            (index for index, row in enumerate(records) if row),
            0,
        )

    def normalize(row):
        row = list(row)
        if len(row) > expected_width:
            row = row[:expected_width - 1] + [",".join(row[expected_width - 1:])]
        elif len(row) < expected_width:
            row.extend([""] * (expected_width - len(row)))
        return [str(value) for value in row]

    columns = normalize(records[header_index]) if records else [""] * expected_width
    rows = [normalize(row) for row in records[header_index + 1:]]
    return {"columns": columns, "rows": rows}
